BEGIN;

CREATE TABLE public.max_users (
	id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
	contact_id integer REFERENCES public.contacts(id) ON DELETE RESTRICT ON UPDATE CASCADE,
	max_user_id bigint NOT NULL,
	username text,
	avatar_url text,
	raw_user jsonb NOT NULL,
	raw_user_with_photo jsonb,
	is_active boolean NOT NULL DEFAULT true
);

COMMENT ON TABLE public.max_users IS 'MAX user reference data.';
COMMENT ON COLUMN public.max_users.contact_id IS 'Contact reference';
COMMENT ON COLUMN public.max_users.max_user_id IS 'MAX user ID';
COMMENT ON COLUMN public.max_users.username IS 'Display name of the MAX user.';
COMMENT ON COLUMN public.max_users.avatar_url IS 'MAX user avatar.';
COMMENT ON COLUMN public.max_users.raw_user IS 'Raw MAX user data.';
COMMENT ON COLUMN public.max_users.raw_user_with_photo IS 'Raw MAX user data containing photo information.';
COMMENT ON COLUMN public.max_users.is_active IS 'Whether the MAX user is active.';

CREATE UNIQUE INDEX max_users_max_user_id_idx
	ON public.max_users USING btree (max_user_id);

CREATE INDEX max_users_contact_id_idx
	ON public.max_users USING btree (contact_id);

WITH required(code, description) AS (
	VALUES
		('maxUser.list', 'Просмотр списка пользователей MAX'),
		('maxUser.detail', 'Просмотр пользователя MAX'),
		('maxUser.update', 'Изменение пользователя MAX'),
		('maxUser.delete', 'Удаление пользователя MAX')
)
INSERT INTO public.permissions (code, description)
SELECT required.code, required.description
FROM required
ON CONFLICT (code) DO UPDATE
SET description = EXCLUDED.description;

WITH roles(role_id) AS (
	VALUES
		('admin'::public.role_types)
), required(permission_code) AS (
	VALUES
		('maxUser.list'),
		('maxUser.detail'),
		('maxUser.update'),
		('maxUser.delete')
)
INSERT INTO public.role_permissions (role_id, permission_code)
SELECT roles.role_id, required.permission_code
FROM roles
CROSS JOIN required
ON CONFLICT DO NOTHING;

INSERT INTO public.application_routes (
	name,
	path,
	descr,
	section,
	icon,
	menu_available,
	is_active
)
VALUES (
